.box {
  width: 200px;
  padding: 20px;
  border: 5px solid black;
  margin: 10px;
}

.container {
  display: flex;
  flex-direction: column;
  height: 300px;
  justify-content: center;
}

const values = [0, "0", [], {}, null, NaN, " ", -1, ""];
let count = 0;
values.forEach((v) => {
  if (v) count++;
});
console.log(count);

const a = { name: "kim", info: { age: 20 } };
const b = { ...a };

b.name = "lee";
b.info.age = 30;

console.log(a.name, a.info.age);

const arr = [1, 2, 3, 4, 5];
const removed = arr.splice(1, 2, "a", "b", "c");

console.log(arr);
console.log(removed);

const calc = {
  PI: 3.14,
  radiuses: [1, 2],
  printArea() {
    this.radiuses.forEach(function (r) {
      console.log(this.PI * r * r);
    });
  },
};

calc.printArea();

// <ul id="list"><li>B</li></ul>
const list = document.querySelector("#list");
const b = list.querySelector("li");

const make = (t) => {
  const li = document.createElement("li");
  li.textContent = t;
  return li;
};

list.prepend(make("C"));
b.after(make("A"));
list.append(make("D"));

